  "signal_basis": {
    "component_id": "C014.signal_basis",
    "value": "Predeclare minimum evidence thresholds before reviewing results from a release comparison measuring first-publication rates, publication timing, checkpoint retention and predefined guardrails.",
    "scope": "Prospective evaluation of the release comparison, with first-publication rates measured within a common window.",
    "provenance": {
      "refs": [
